import SwiftUI

/// The Tinglang mark: a thin, sharp sound wave that softens and thickens into a
/// rounded "hi". Geometry and colours come from assets/brand/svg through
/// BrandMarkGeometry.swift (generated by tools/brand_mark_geometry.py).
struct BrandMark: View {
  /// The panel is dark glass, so it defaults to the on-dark colours (orange to paper).
  var onDark = true

  var body: some View {
    Canvas { context, size in
      // Below 48 pt the small-size drawing (heavier strokes, larger dot) reads better.
      let regular = Self.regular.viewBox
      let width = min(size.width, size.height * regular.width / regular.height)
      let drawing = width < 48 ? Self.small : Self.regular
      let box = drawing.viewBox
      let scale = min(size.width / box.width, size.height / box.height)
      context.translateBy(
        x: (size.width - box.width * scale) / 2, y: (size.height - box.height * scale) / 2)
      context.scaleBy(x: scale, y: scale)
      context.translateBy(x: -box.minX, y: -box.minY)
      let colors = onDark ? drawing.dark : drawing.light
      // Like the SVG's userSpaceOnUse gradient: viewBox coordinates.
      let shading = GraphicsContext.Shading.linearGradient(
        Gradient(stops: colors.stops), startPoint: drawing.gradientStart,
        endPoint: drawing.gradientEnd)
      context.fill(drawing.wave, with: shading)
      context.stroke(
        drawing.letters, with: shading,
        style: StrokeStyle(lineWidth: drawing.strokeWidth, lineCap: .round, lineJoin: .round))
      context.fill(drawing.dot, with: .color(colors.dot))
    }
    .accessibilityHidden(true)
  }
}
